/**
 * Local symbol index — replaces the stockanalysis.com search endpoint, which
 * stopped allowing browser (CORS) reads in Nov 2026.
 *
 * The index is a static asset (`public/tickers.json`) generated by
 * `scripts/build-tickers.mjs` from the free Nasdaq trader symbol directory
 * (every US-listed stock and ETF). Matching happens in memory: it cannot be
 * rate-limited, goes offline, or breaks when a provider changes its policy.
 */

import type { AssetKind, SearchHit } from "./types";

/** One row of the compact index: [symbol, name, kind-flag]. */
export type IndexRow = [string, string, "s" | "e"];

export interface TickerIndex {
  v: number;
  updated: string;
  rows: IndexRow[];
}

export interface IndexedSymbol {
  symbol: string;
  name: string;
  kind: AssetKind;
}

const INDEX_URL = `${import.meta.env.BASE_URL}tickers.json`;

/** Column indices for the compact row format. */
const SYM = 0;
const NAME = 1;
const KIND = 2;

let indexPromise: Promise<IndexedSymbol[]> | null = null;

/** Parse the raw asset payload into indexed symbols (pure, testable). */
export function parseIndex(payload: TickerIndex | null | undefined): IndexedSymbol[] {
  const rows = payload?.rows ?? [];
  return rows
    .filter((r): r is IndexRow => Array.isArray(r) && typeof r[SYM] === "string" && r[SYM].length > 0)
    .map((r) => ({
      symbol: r[SYM],
      name: typeof r[NAME] === "string" && r[NAME].length > 0 ? r[NAME] : r[SYM],
      kind: (r[KIND] === "e" ? "etf" : "stock") as AssetKind,
    }));
}

/** Load the index once per session; a failure clears the memo so Retry works. */
export function loadIndex(): Promise<IndexedSymbol[]> {
  if (!indexPromise) {
    indexPromise = fetch(INDEX_URL)
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status} for ${INDEX_URL}`);
        return res.json() as Promise<TickerIndex>;
      })
      .then(parseIndex)
      .catch((err) => {
        indexPromise = null;
        throw err;
      });
  }
  return indexPromise;
}

/** Reset the memoized index (tests). */
export function resetIndex(): void {
  indexPromise = null;
}

/** Word-prefix match: "apple" matches "Apple Inc." but not "Snapple Corp". */
function startsWord(haystack: string, needle: string): boolean {
  let at = haystack.indexOf(needle);
  while (at !== -1) {
    if (at === 0 || !/[a-z0-9]/i.test(haystack[at - 1])) return true;
    at = haystack.indexOf(needle, at + 1);
  }
  return false;
}

/**
 * Rank symbols for a query. Cheap and deterministic:
 *   0 exact ticker, 1 ticker prefix, 2 name word-prefix,
 *   3 ticker contains, 4 name contains.
 * Ties favour the shorter (usually primary) ticker, then alphabetical order.
 */
export function matchSymbols(
  index: IndexedSymbol[],
  query: string,
  limit = 10,
): SearchHit[] {
  const q = query.trim().toUpperCase();
  if (!q) return [];
  const lower = q.toLowerCase();

  const scored: { hit: SearchHit; score: number }[] = [];
  for (const row of index) {
    const symbol = row.symbol.toUpperCase();
    const name = row.name;
    const nameLower = name.toLowerCase();

    let score: number;
    if (symbol === q) score = 0;
    else if (symbol.startsWith(q)) score = 1;
    else if (startsWord(nameLower, lower)) score = 2;
    else if (symbol.includes(q)) score = 3;
    else if (nameLower.includes(lower)) score = 4;
    else continue;

    scored.push({ hit: { symbol: row.symbol, name, kind: row.kind }, score });
  }

  scored.sort((a, b) => {
    if (a.score !== b.score) return a.score - b.score;
    if (a.hit.symbol.length !== b.hit.symbol.length) {
      return a.hit.symbol.length - b.hit.symbol.length;
    }
    return a.hit.symbol < b.hit.symbol ? -1 : a.hit.symbol > b.hit.symbol ? 1 : 0;
  });

  return scored.slice(0, limit).map((s) => s.hit);
}

/** Search the local index (loads it on first use). */
export async function searchSymbolsLocal(query: string, limit = 10): Promise<SearchHit[]> {
  if (!query.trim()) return [];
  const index = await loadIndex();
  return matchSymbols(index, query, limit);
}
